import { createRoute, z } from '@hono/zod-openapi'

type AiGatewayEvaluationFallbackConditionType =
  | { confidenceBelow: number; question?: string }
  | { probabilityBetween: number[]; question?: string }
  | { any: AiGatewayEvaluationFallbackConditionType[] }
  | { all: AiGatewayEvaluationFallbackConditionType[] }
  | { atLeast: { conditions: AiGatewayEvaluationFallbackConditionType[]; count: number } }

type FlagJSONValueType =
  | (string | number | FlagJSONValueType[] | { [key: string]: FlagJSONValueType } | false | true)
  | null

type GlobalConfigItemValueType =
  | (
      | string
      | number
      | { [key: string]: GlobalConfigItemValueType }
      | GlobalConfigItemValueType[]
      | false
      | true
    )
  | null

type FileTreeType = {
  children?: FileTreeType[]
  contentType?: string
  mode: number
  name: string
  type: 'directory' | 'file' | 'invalid' | 'lambda' | 'middleware' | 'symlink'
  uid?: string
}

const AiGatewayEvaluationFallbackConditionSchema: z.ZodType<AiGatewayEvaluationFallbackConditionType> =
  z
    .lazy(() =>
      z.xor([
        z
          .object({ confidenceBelow: z.number(), question: z.string().exactOptional() })
          .openapi({
            required: ['confidenceBelow'],
            description: 'Without a question, checks every Choice and Score question.',
          }),
        z
          .object({
            probabilityBetween: z.array(z.number()).length(2),
            question: z.string().exactOptional(),
          })
          .openapi({
            required: ['probabilityBetween'],
            description: 'Without a question, checks every Boolean question.',
          }),
        z
          .object({ any: z.array(AiGatewayEvaluationFallbackConditionSchema) })
          .openapi({ required: ['any'] }),
        z
          .object({ all: z.array(AiGatewayEvaluationFallbackConditionSchema) })
          .openapi({ required: ['all'] }),
        z
          .object({
            atLeast: z
              .object({
                conditions: z.array(AiGatewayEvaluationFallbackConditionSchema),
                count: z.number(),
              })
              .openapi({ required: ['conditions', 'count'] }),
          })
          .openapi({ required: ['atLeast'] }),
      ]),
    )
    .openapi('AiGatewayEvaluationFallbackCondition')

