const PrivateLinkEndpointSchema = z
  .object({
    awsDnsEntries: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'The regional DNS names assigned to the endpoint by AWS. Use these to reach the service when private DNS is not enabled.',
        example: [
          'vpce-0123456789abcdef0-a1b2c3d4.vpce-svc-0123456789abcdef0.us-east-1.vpce.amazonaws.com',
        ],
      }),
    awsServiceName: z
      .string()
      .openapi({
        description: 'The AWS VPC endpoint service the endpoint connects to.',
        example: 'com.amazonaws.vpce.us-east-1.vpce-svc-0123456789abcdef0',
      }),
    createdAt: z
      .number()
      .openapi({
        description:
          'Timestamp in milliseconds since the UNIX epoch for when the endpoint was created.',
        example: 1610963878358,
      }),
    endpointId: z
      .string()
      .openapi({
        description: 'The unique identifier of the PrivateLink endpoint.',
        example: 'ple_a1b2c3d4e5f6g7h8',
      }),
    name: z
      .string()
      .openapi({
        description: 'The name of the PrivateLink endpoint, shown in the Vercel dashboard.',
        example: 'payments-db',
      }),
    privateDnsNames: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'The private DNS names of the endpoint service, populated when private DNS is enabled for the endpoint.',
        example: ['payments.internal.example.com'],
      }),
    projectId: z
      .string()
      .openapi({
        description: 'The identifier of the project the PrivateLink endpoint belongs to.',
        example: 'prj_a1b2c3d4e5f6g7h8',
      }),
    status: z
      .enum([
        'available',
        'creating',
        'deleting',
        'failed',
        'pending-acceptance',
        'provisioning',
        'rejected',
      ])
      .openapi({
        description:
          'The current state of the endpoint. - `creating`: the endpoint is being created. - `pending-acceptance`: waiting for the endpoint service owner to accept the connection. Only occurs for services that require manual acceptance. - `provisioning`: the connection was accepted and AWS is finishing setup. - `available`: the endpoint is fully provisioned and ready to use. - `rejected`: the endpoint service owner rejected the connection. - `failed`: the endpoint could not be provisioned. - `deleting`: the endpoint is being deleted.',
        example: 'available',
      }),
    statusMessage: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A human-readable explanation of why the endpoint could not be provisioned. Only set when `status` is `failed`, and absent for every other status including `rejected`, since AWS does not report a rejection reason.',
        example:
          'Endpoint did not become available in time. Try deleting and recreating, or visit https://vercel.com/help if the issue persists.',
      }),
    teamId: z
      .string()
      .openapi({
        description: 'The identifier of the team that owns the PrivateLink endpoint.',
        example: 'team_a1b2c3d4e5f6g7h8',
      }),
    updatedAt: z
      .number()
      .openapi({
        description:
          'Timestamp in milliseconds since the UNIX epoch for when the endpoint was last updated.',
        example: 1610963878358,
      }),
    vercelRegion: z
      .string()
      .openapi({
        description: 'The Vercel region the endpoint is provisioned in.',
        example: 'iad1',
      }),
    vpcEndpointId: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The identifier of the underlying AWS VPC endpoint. Absent until AWS has created the endpoint.',
        example: 'vpce-0123456789abcdef0',
      }),
  })
  .openapi({
    required: [
      'awsServiceName',
      'createdAt',
      'endpointId',
      'name',
      'projectId',
      'status',
      'teamId',
      'updatedAt',
      'vercelRegion',
    ],
    description:
      'A PrivateLink endpoint, which connects a project to an AWS VPC endpoint service in a single region so that traffic reaches the service over AWS PrivateLink rather than the public internet.',
  })
  .openapi('PrivateLinkEndpoint')

