const RegistrantFieldSchema = z
  .union([
    z
      .strictObject({
        description: z.string(),
        required: z.boolean(),
        label: z.string().exactOptional(),
        validation: z.string().exactOptional(),
        required_when: z
          .union([
            z.string(),
            z.strictObject({ value_in: z.array(z.string()) }).openapi({ required: ['value_in'] }),
          ])
          .exactOptional(),
        type: z.literal('string'),
        options: z
          .array(
            z
              .strictObject({
                value: z.string(),
                label: z.string(),
                fields: z.object({}).exactOptional(),
              })
              .openapi({ required: ['value', 'label'] }),
          )
          .exactOptional(),
        fields: z.object({}).exactOptional(),
      })
      .openapi({ required: ['description', 'required', 'type'] }),
    z
      .strictObject({
        description: z.string(),
        required: z.boolean(),
        label: z.string().exactOptional(),
        validation: z.string().exactOptional(),
        required_when: z
          .union([
            z.string(),
            z.strictObject({ value_in: z.array(z.string()) }).openapi({ required: ['value_in'] }),
          ])
          .exactOptional(),
        type: z.literal('enum'),
        options: z.array(
          z
            .strictObject({
              value: z.string(),
              label: z.string(),
              fields: z.object({}).exactOptional(),
            })
            .openapi({ required: ['value', 'label'] }),
        ),
        fields: z.object({}).exactOptional(),
      })
      .openapi({ required: ['description', 'required', 'type', 'options'] }),
    z
      .strictObject({
        description: z.string(),
        required: z.boolean(),
        label: z.string().exactOptional(),
        validation: z.string().exactOptional(),
        required_when: z
          .union([
            z.string(),
            z.strictObject({ value_in: z.array(z.string()) }).openapi({ required: ['value_in'] }),
          ])
          .exactOptional(),
        type: z.literal('acknowledgement'),
        value: z.string().exactOptional(),
      })
      .openapi({ required: ['description', 'required', 'type'] }),
    z
      .strictObject({
        description: z.string(),
        required: z.boolean(),
        label: z.string().exactOptional(),
        validation: z.string().exactOptional(),
        required_when: z
          .union([
            z.string(),
            z.strictObject({ value_in: z.array(z.string()) }).openapi({ required: ['value_in'] }),
          ])
          .exactOptional(),
        type: z.literal('notice'),
      })
      .openapi({ required: ['description', 'required', 'type'] }),
  ])
  .openapi({ description: 'Schema definition for registrant fields.' })
  .openapi('RegistrantField')

