const GlobalConfigItemValueSchema: z.ZodType<GlobalConfigItemValueType> = z
  .lazy(() =>
    z
      .xor([
        z.string(),
        z.number(),
        z.record(z.string(), GlobalConfigItemValueSchema),
        z.array(GlobalConfigItemValueSchema),
        z.union([z.literal(false), z.literal(true)]),
      ])
      .nullable(),
  )
  .openapi('GlobalConfigItemValue')

