const APIKeySchema = z
  .object({
    id: z
      .string()
      .openapi({
        description: 'The unique identifier of the API key.',
        example: '5d9f2ebd38ddca62e5d51e9c1704c72530bdc8bfdd41e782a6687c48399e8391',
      }),
    name: z
      .string()
      .openapi({
        description: 'The human-readable name of the API key.',
        example: 'API Key for AI Gateway',
      }),
    partialKey: z
      .string()
      .openapi({
        description:
          'The last few characters of the API key string, for helping identify the API key.',
        example: 't7V',
      }),
    teamId: z
      .string()
      .openapi({
        description: 'The ID of the team that the API key grants access to.',
        example: 'team_123a6c5209bc3778245d011443644c8d27dc2c50',
      }),
    purpose: z
      .string()
      .openapi({
        description: "The API key's purpose, i.e. what resources it can be used with.",
        example: 'ai-gateway',
      }),
    projectId: z
      .string()
      .nullable()
      .openapi({
        description:
          'The ID of the project that this API key grants access to.\n\nWhen this is unset, the API key grants access to all projects in the team.',
        example: 'prj_12HKQaOmR5t5Uy6vdcQsNIiZgHGB',
      }),
    expiresAt: z
      .number()
      .nullable()
      .openapi({
        description: 'Timestamp (in milliseconds) of when the API key expires.',
        example: 1632816536002,
      }),
    activeAt: z
      .number()
      .openapi({
        description: 'Timestamp (in milliseconds) of when the API key was most recently used.',
        example: 1632816536002,
      }),
    createdAt: z
      .number()
      .openapi({
        description: 'Timestamp (in milliseconds) of when the API key was created.',
        example: 1632816536002,
      }),
    createdBy: z
      .string()
      .openapi({
        description: 'The ID of the user who created the API key.',
        example: 'ZspSRT4ljIEEmMHgoDwKWDei',
      }),
    leakedAt: z
      .number()
      .nullable()
      .openapi({
        description: 'Timestamp (in milliseconds) of when the API key was marked as leaked.',
        example: 1632816536002,
      }),
    leakedUrl: z
      .string()
      .nullable()
      .openapi({ description: 'URL where the API key was discovered as leaked.' }),
    createdByAppId: z
      .string()
      .nullable()
      .openapi({ description: 'The ID of the app that created the API key, if any' }),
    quota: APIKeyQuotaSchema.exactOptional(),
    metadata: z
      .looseObject({})
      .superRefine((o, ctx) => {
        const regex = new RegExp('^(.*)$')
        const Schema = z.any()
        for (const [k, val] of Object.entries(o)) {
          if (!regex.test(k)) {
            continue
          }
          const result = Schema.safeParse(val)
          if (!result.success) {
            for (const issue of result.error.issues) {
              ctx.addIssue({ ...issue, path: [k, ...issue.path] })
            }
          }
        }
      })
      .exactOptional()
      .openapi({
        description:
          "Generic metadata attached to the API key.\n\nThe accepted shape depends on the key's `purpose` and is validated when the key is created. For `ai-gateway` keys this carries `environment` and `spendAttribution`.",
      }),
  })
  .openapi({
    description: 'Represents an API key.',
    required: [
      'id',
      'name',
      'partialKey',
      'teamId',
      'purpose',
      'projectId',
      'expiresAt',
      'activeAt',
      'createdAt',
      'createdBy',
      'leakedAt',
      'leakedUrl',
      'createdByAppId',
    ],
  })
  .openapi('APIKey')

