const AuthUserLimitedSchema = z
  .object({
    avatar: z
      .string()
      .nullable()
      .openapi({
        description:
          'SHA1 hash of the avatar for the User account. Can be used in conjuction with the ... endpoint to retrieve the avatar image.',
        example: '22cb30c85ff45ac4c72de8981500006b28114aa1',
      }),
    defaultTeamId: z.string().nullable().openapi({ description: "The user's default team." }),
    email: z
      .string()
      .openapi({
        description: 'Email address associated with the User account.',
        example: 'me@example.com',
      }),
    id: z
      .string()
      .openapi({
        description: "The User's unique identifier.",
        example: 'AEIIDYVk59zbFF2Sxfyxxmua',
      }),
    isEnterpriseManaged: z
      .union([z.literal(false), z.literal(true)])
      .exactOptional()
      .openapi({ description: 'Indicates whether the user is managed by an enterprise.' }),
    limited: z
      .literal(true)
      .openapi({
        description:
          'Property indicating that this User data contains only limited information, due to the authentication token missing privileges to read the full User data. Re-login with email, GitHub, GitLab or Bitbucket in order to upgrade the authentication token with the necessary privileges.',
      }),
    name: z
      .string()
      .nullable()
      .openapi({
        description: 'Name associated with the User account, or `null` if none has been provided.',
        example: 'John Doe',
      }),
    shouldShowEnterpriseManagedWelcome: z
      .union([z.literal(false), z.literal(true)])
      .exactOptional()
      .openapi({
        description:
          'Whether the Enterprise Managed User joined the current team through the Update Account flow and should see its welcome experience.',
      }),
    username: z
      .string()
      .openapi({
        description: 'Unique username associated with the User account.',
        example: 'jdoe',
      }),
  })
  .openapi({
    required: ['avatar', 'defaultTeamId', 'email', 'id', 'limited', 'name', 'username'],
    description:
      'A limited form of data for the currently authenticated User, due to the authentication token missing privileges to read the full User data.',
  })
  .openapi('AuthUserLimited')

const VcrRepositorySchema = z
  .object({
    createdAt: z
      .string()
      .openapi({
        description: 'ISO 8601 timestamp of when the repository was created.',
        example: '2026-06-30T10:00:00.000Z',
      }),
    id: z
      .string()
      .openapi({
        description: 'Unique identifier of the repository.',
        example: 'repo_a1b2c3d4e5f6',
      }),
    name: z.string().openapi({ description: 'Name of the repository.', example: 'my-app' }),
    projectId: z
      .string()
      .openapi({
        description: 'Identifier of the project the repository belongs to.',
        example: 'prj_a1b2c3d4e5f6',
      }),
    public: z
      .union([z.literal(false), z.literal(true)])
      .openapi({
        description:
          'Whether the repository is public. Images in public repositories can be pulled by anyone. Defaults to `false` (private).',
        example: false,
      }),
    updatedAt: z
      .string()
      .openapi({
        description: 'ISO 8601 timestamp of when the repository was last updated.',
        example: '2026-06-30T10:00:00.000Z',
      }),
  })
  .openapi({
    required: ['createdAt', 'id', 'name', 'projectId', 'public', 'updatedAt'],
    description: 'A Vercel Container Registry repository.',
  })
  .openapi('VcrRepository')

const VcrRepositoryListSchema = z
  .object({
    nextCursor: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Cursor to fetch the next page of results, when more are available.',
      }),
    repositories: z.array(VcrRepositorySchema),
  })
  .openapi({
    required: ['repositories'],
    description: 'A paginated list of Vercel Container Registry repositories.',
  })
  .openapi('VcrRepositoryList')

const VcrImageListItemSchema = z
  .object({
    arch: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'CPU architecture the manifest targets. Only present for single-platform manifests.',
        example: 'amd64',
      }),
    createdAt: z
      .string()
      .openapi({
        description: 'ISO 8601 timestamp of when the image was created.',
        example: '2026-06-30T10:00:00.000Z',
      }),
    id: z
      .string()
      .openapi({ description: 'Internal identifier of the image.', example: 'img_a1b2c3d4e5f6' }),
    kind: z
      .enum(['attestation', 'index', 'manifest'])
      .openapi({
        description:
          'Whether the manifest is a multi-platform image index, a single-platform image manifest or an attestation.',
      }),
    manifestDigest: z
      .string()
      .openapi({
        description: 'SHA-256 digest of the image manifest.',
        example: 'sha256:2c4e8f3a1b9d0e5c7a6f4b2d8e1c9a0b3d5f7e9c1a2b4d6f8e0c2a4b6d8f0e2c',
      }),
    platform: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Operating system the manifest targets. Only present for single-platform manifests.',
        example: 'linux',
      }),
    pushedBy: z
      .string()
      .exactOptional()
      .openapi({ description: 'Identifier of the actor that pushed the image.' }),
    repositoryId: z
      .string()
      .openapi({
        description: 'Identifier of the repository the image belongs to.',
        example: 'repo_a1b2c3d4e5f6',
      }),
    sizeInBytes: z
      .number()
      .openapi({
        description:
          "Total size in bytes of the image's resources (manifest, config and layer blobs) stored by the registry.",
      }),
    status: z
      .union([
        z.literal('errored'),
        z.literal('preparing'),
        z.literal('ready'),
        z.literal('unoptimized'),
        z.literal(null),
      ])
      .nullable()
      .openapi({ description: 'VHS-readiness status, or `null` for a multi-platform index.' }),
    tags: z.array(z.string()).openapi({ description: "Tags pointing at this image's manifest." }),
  })
  .openapi({
    required: [
      'createdAt',
      'id',
      'kind',
      'manifestDigest',
      'repositoryId',
      'sizeInBytes',
      'status',
      'tags',
    ],
    description:
      "An image enriched with its tags and VHS-readiness status, as returned when listing a repository's images.",
  })
  .openapi('VcrImageListItem')

const VcrImageListSchema = z
  .object({
    images: z.array(VcrImageListItemSchema),
    nextCursor: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Cursor to fetch the next page of results, when more are available.',
      }),
  })
  .openapi({ required: ['images'], description: 'A paginated list of images for a repository.' })
  .openapi('VcrImageList')

