const VercelBaseErrorSchema = z
  .object({ code: z.string(), message: z.string() })
  .openapi({ required: ['code', 'message'] })
  .openapi('VercelBaseError')

const VercelForbiddenErrorSchema = z
  .object({
    error: VercelBaseErrorSchema.and(
      z.object({ code: z.string() }).openapi({ required: ['code'] }),
    ),
  })
  .openapi({ required: ['error'] })
  .openapi('VercelForbiddenError')

const VercelNotFoundErrorSchema = z
  .object({
    error: VercelBaseErrorSchema.and(
      z
        .object({ code: z.string(), message: z.string().exactOptional() })
        .openapi({ required: ['code'] }),
    ),
  })
  .openapi({ required: ['error'] })
  .openapi('VercelNotFoundError')

const VercelBadRequestErrorSchema = z
  .object({
    error: VercelBaseErrorSchema.and(
      z
        .object({ code: z.string(), message: z.string().exactOptional() })
        .openapi({ required: ['code'] }),
    ),
  })
  .openapi({ required: ['error'] })
  .openapi('VercelBadRequestError')

const RateLimitNoticeSchema = z
  .object({
    remaining: z.int().min(0),
    reset: z.int().min(0),
    resetMs: z.int().min(0),
    total: z.int().min(0),
  })
  .openapi({ required: ['remaining', 'reset', 'resetMs', 'total'] })
  .openapi('RateLimitNotice')

const VercelRateLimitErrorSchema = z
  .object({
    error: VercelBaseErrorSchema.and(
      z
        .object({ code: z.string(), limit: RateLimitNoticeSchema.exactOptional() })
        .openapi({ required: ['code'] }),
    ),
  })
  .openapi({ required: ['error'] })
  .openapi('VercelRateLimitError')

