export const putV8ArtifactsHashRoute = createRoute({
  method: 'put',
  path: '/v8/artifacts/{hash}',
  tags: ['artifacts'],
  summary: 'Upload a cache artifact',
  description:
    'Uploads a cache artifact identified by the `hash` specified on the path. The cache artifact can then be downloaded with the provided `hash`.',
  operationId: 'uploadArtifact',
  request: {
    headers: z.object({
      'Content-Length': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .openapi({
          param: {
            in: 'header',
            description: 'The artifact size in bytes',
            required: true,
            schema: { description: 'The artifact size in bytes', type: 'number' },
            name: 'Content-Length',
          },
          description: 'The artifact size in bytes',
        }),
      'x-artifact-duration': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'header',
            description: 'The time taken to generate the uploaded artifact in milliseconds.',
            required: false,
            schema: {
              type: 'number',
              description: 'The time taken to generate the uploaded artifact in milliseconds.',
              example: 400,
            },
            name: 'x-artifact-duration',
          },
          description: 'The time taken to generate the uploaded artifact in milliseconds.',
          example: 400,
        }),
      'x-artifact-client-ci': z
        .string()
        .max(50)
        .exactOptional()
        .openapi({
          param: {
            in: 'header',
            description:
              'The continuous integration or delivery environment where this artifact was generated.',
            required: false,
            schema: {
              type: 'string',
              description:
                'The continuous integration or delivery environment where this artifact was generated.',
              example: 'VERCEL',
              maxLength: 50,
            },
            name: 'x-artifact-client-ci',
          },
          description:
            'The continuous integration or delivery environment where this artifact was generated.',
          example: 'VERCEL',
        }),
      'x-artifact-client-interactive': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(0).max(1),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'header',
            description: '1 if the client is an interactive shell. Otherwise 0',
            required: false,
            schema: {
              type: 'integer',
              description: '1 if the client is an interactive shell. Otherwise 0',
              example: 0,
              minimum: 0,
              maximum: 1,
            },
            name: 'x-artifact-client-interactive',
          },
          description: '1 if the client is an interactive shell. Otherwise 0',
          example: 0,
        }),
      'x-artifact-tag': z
        .string()
        .max(600)
        .exactOptional()
        .openapi({
          param: {
            in: 'header',
            description:
              'The base64 encoded tag for this artifact. The value is sent back to clients when the artifact is downloaded as the header `x-artifact-tag`',
            required: false,
            schema: {
              type: 'string',
              description:
                'The base64 encoded tag for this artifact. The value is sent back to clients when the artifact is downloaded as the header `x-artifact-tag`',
              example: 'Tc0BmHvJYMIYJ62/zx87YqO0Flxk+5Ovip25NY825CQ=',
              maxLength: 600,
            },
            name: 'x-artifact-tag',
          },
          description:
            'The base64 encoded tag for this artifact. The value is sent back to clients when the artifact is downloaded as the header `x-artifact-tag`',
          example: 'Tc0BmHvJYMIYJ62/zx87YqO0Flxk+5Ovip25NY825CQ=',
        }),
      'x-artifact-sha': z
        .string()
        .max(200)
        .exactOptional()
        .openapi({
          param: {
            in: 'header',
            description: 'The SHA of the source control revision that generated this artifact.',
            required: false,
            schema: {
              type: 'string',
              description: 'The SHA of the source control revision that generated this artifact.',
              maxLength: 200,
            },
            name: 'x-artifact-sha',
          },
          description: 'The SHA of the source control revision that generated this artifact.',
        }),
      'x-artifact-dirty-hash': z
        .string()
        .max(200)
        .exactOptional()
        .openapi({
          param: {
            in: 'header',
            description:
              'A hash representing uncommitted changes in the working directory when this artifact was generated.',
            required: false,
            schema: {
              type: 'string',
              description:
                'A hash representing uncommitted changes in the working directory when this artifact was generated.',
              maxLength: 200,
            },
            name: 'x-artifact-dirty-hash',
          },
          description:
            'A hash representing uncommitted changes in the working directory when this artifact was generated.',
        }),
    }),
    params: z.object({
      hash: z
        .string()
        .openapi({
          param: {
            name: 'hash',
            description: 'The artifact hash',
            in: 'path',
            required: true,
            schema: {
              example: '12HKQaOmR5t5Uy6vdcQsNIiZgHGB',
              description: 'The artifact hash',
              type: 'string',
            },
          },
          example: '12HKQaOmR5t5Uy6vdcQsNIiZgHGB',
          description: 'The artifact hash',
        }),
    }),
    query: z.object({
      teamId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The Team identifier to perform the request on behalf of.',
            in: 'query',
            name: 'teamId',
            schema: { type: 'string', example: 'team_1a2b3c4d5e6f7g8h9i0j1k2l' },
            required: false,
          },
          example: 'team_1a2b3c4d5e6f7g8h9i0j1k2l',
        }),
      slug: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The Team slug to perform the request on behalf of.',
            in: 'query',
            name: 'slug',
            schema: { type: 'string', example: 'my-team-url-slug' },
            required: false,
          },
          example: 'my-team-url-slug',
        }),
    }),
    body: {
      content: {
        'application/octet-stream': {
          schema: z.file().openapi({ type: 'string', format: 'binary' }),
        },
      },
      required: true,
    },
  },
  responses: {
    202: {
      description: 'File successfully uploaded',
      content: {
        'application/json': {
          schema: z.object({ urls: z.array(z.string()) }).openapi({ required: ['urls'] }),
        },
      },
    },
    400: {
      description:
        'One of the provided values in the request query is invalid.\nOne of the provided values in the headers is invalid\nFile size is not valid',
    },
    401: { description: 'The request is not authorized.' },
    402: { description: 'The account is missing a payment so payment method must be updated' },
    403: {
      description:
        'The customer has reached their spend cap limit and has been paused. An owner can disable the cap or raise the limit in settings.\nThe Remote Caching usage limit has been reached for this account for this billing cycle.\nRemote Caching has been disabled for this team or user. An owner can enable it in the billing settings.\nYou do not have permission to access this resource.',
    },
    404: { description: '' },
    410: { description: '' },
  },
  security: [{ bearerToken: [] }],
})

