export const postV1NetworkingPrivatelinkEndpointsRoute = createRoute({
  method: 'post',
  path: '/v1/networking/privatelink/endpoints',
  tags: ['networking'],
  summary: 'Create a PrivateLink endpoint',
  description:
    'Creates a PrivateLink endpoint for a project. Changes to endpoints of the same project are serialized. If another change holds them for too long, the request fails with `503 service_unavailable` and can be retried. If the change may have completed but the outcome is unknown, it fails with `409 uncertain_outcome`; read the endpoint before retrying.',
  operationId: 'createPrivateLinkEndpoint',
  request: {
    query: z.object({
      teamId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The Team identifier to perform the request on behalf of.',
            in: 'query',
            name: 'teamId',
            schema: { type: 'string', example: 'team_1a2b3c4d5e6f7g8h9i0j1k2l' },
            required: false,
          },
          example: 'team_1a2b3c4d5e6f7g8h9i0j1k2l',
        }),
      slug: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The Team slug to perform the request on behalf of.',
            in: 'query',
            name: 'slug',
            schema: { type: 'string', example: 'my-team-url-slug' },
            required: false,
          },
          example: 'my-team-url-slug',
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              projectId: z
                .string()
                .openapi({
                  description: 'The project ID to create the PrivateLink endpoint for.',
                  example: 'prj_a1b2c3d4e5f6g7h8',
                }),
              name: z
                .string()
                .max(255)
                .openapi({
                  description:
                    'The name of the PrivateLink endpoint, used as its label in the Vercel dashboard.',
                  example: 'payments-db',
                }),
              vercelRegion: z
                .string()
                .openapi({
                  description:
                    'The Vercel region to provision the endpoint in. Advanced Networking must be enabled for the project in that region. The endpoint service itself may live in another AWS region.',
                  example: 'iad1',
                }),
              awsServiceName: z
                .string()
                .openapi({
                  description:
                    'The name of the AWS VPC endpoint service to connect to. Its AWS region is read from the name; when that region differs from the one behind `vercelRegion`, the service must allow cross-region access.',
                  example: 'com.amazonaws.vpce.us-east-1.vpce-svc-0123456789abcdef0',
                }),
              enablePrivateDns: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Whether to resolve the endpoint service through its private DNS names, which are then returned in `privateDnsNames`. Defaults to `false`, in which case the endpoint is reachable through the DNS names in `awsDnsEntries`.',
                  example: false,
                }),
            })
            .openapi({ required: ['projectId', 'name', 'vercelRegion', 'awsServiceName'] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'The PrivateLink endpoint was created and is being provisioned.',
      content: { 'application/json': { schema: PrivateLinkEndpointSchema } },
    },
    400: { description: 'One of the provided values in the request body is invalid.' },
    401: { description: 'The request is not authorized.' },
    403: { description: 'You do not have permission to access this resource.' },
    404: { description: '' },
    409: { description: '' },
    410: { description: '' },
    500: { description: '' },
    503: { description: '' },
  },
  security: [{ bearerToken: [] }],
})

