export const postV1ConnectTokenConnectorRoute = createRoute({
  method: 'post',
  path: '/v1/connect/token/{connector}',
  tags: ['connect'],
  summary: 'Get a Connect token',
  description:
    'Get an access token for a connector identified by the path parameter and scoped to the requester.',
  operationId: 'getConnectorToken',
  request: {
    params: z.object({
      connector: z
        .string()
        .openapi({
          param: { name: 'connector', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              subject: z
                .union([
                  z
                    .looseObject({ type: z.literal('app') })
                    .openapi({ title: 'type:app', required: ['type'] }),
                  z
                    .looseObject({
                      type: z.literal('user'),
                      id: z.string().exactOptional(),
                      issuer: z.string().exactOptional(),
                    })
                    .openapi({ title: 'type:user', required: ['type'] }),
                  z
                    .looseObject({
                      type: z.literal('jwt-bearer'),
                      sub: z.string().exactOptional(),
                      iss: z.string().exactOptional(),
                      aud: z.string().exactOptional(),
                      additionalClaims: z.looseObject({}).exactOptional(),
                    })
                    .openapi({ title: 'type:jwt-bearer', required: ['type'] }),
                  z
                    .strictObject({ type: z.literal('token'), token: z.string() })
                    .openapi({ title: 'type:token', required: ['type', 'token'] }),
                  z
                    .looseObject({ type: z.string().exactOptional() })
                    .openapi({ required: [] })
                    .refine(
                      (val) =>
                        !z
                          .object({ type: z.enum(['app', 'user', 'jwt-bearer', 'token']) })
                          .openapi({ required: ['type'] })
                          .safeParse(val).success,
                    )
                    .openapi({ title: 'type:other', required: ['type'] }),
                ])
                .exactOptional(),
              installationId: z.string().exactOptional(),
              audience: z.array(z.string()).exactOptional(),
              scopes: z.array(z.string()).exactOptional(),
              resources: z.array(z.string()).exactOptional(),
              authorizationDetails: z
                .array(
                  z.looseObject({ type: z.string().exactOptional() }).openapi({ required: [] }),
                )
                .exactOptional(),
              validityBufferMs: z.number().exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              authorizationId: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Stable id correlating all tokens (including refreshes) back to the original authorization.',
                }),
              claims: z
                .looseObject({})
                .exactOptional()
                .openapi({
                  description:
                    "Claims extracted from the provider's tokens per the connector's `ForwardedClaims` allow-list. Currently sourced from the OIDC id_token only.",
                }),
              connector: z
                .object({
                  id: z.string(),
                  service: z.string().exactOptional(),
                  type: z.string(),
                  uid: z.string(),
                })
                .openapi({ required: ['id', 'type', 'uid'] }),
              expiresAt: z.number(),
              externalSubject: z.string().exactOptional(),
              installationId: z.string().exactOptional(),
              metadata: z
                .looseObject({})
                .exactOptional()
                .openapi({ description: 'Driver-specific metadata (e.g., botUserId for Slack).' }),
              name: z.string().exactOptional(),
              tenantId: z.string().exactOptional(),
              token: z.string(),
              tokenGroupId: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Stable id that groups all tokens with the same parameters across refreshes.',
                }),
              tokenId: z.string(),
            })
            .openapi({ required: ['connector', 'expiresAt', 'token', 'tokenId'] }),
        },
      },
    },
    400: {
      description:
        'One of the provided values in the request body is invalid.\nOne of the provided values in the request query is invalid.',
    },
    401: { description: 'The request is not authorized.' },
    403: { description: 'You do not have permission to access this resource.' },
    404: { description: '' },
    409: { description: '' },
    410: { description: '' },
    422: { description: '' },
    429: { description: '' },
    500: { description: '' },
  },
  security: [{ bearerToken: [] }],
})

