export const patchV1DeploymentsDeploymentIdIntegrationsIntegrationConfigurationIdResourcesResourceIdActionsActionRoute =
  createRoute({
    method: 'patch',
    path: '/v1/deployments/{deploymentId}/integrations/{integrationConfigurationId}/resources/{resourceId}/actions/{action}',
    tags: ['deployments', 'integrations'],
    summary: 'Update deployment integration action',
    description:
      'Updates the deployment integration action for the specified integration installation',
    operationId: 'update-integration-deployment-action',
    request: {
      params: z.object({
        deploymentId: z
          .string()
          .openapi({
            param: { name: 'deploymentId', in: 'path', required: true, schema: { type: 'string' } },
          }),
        integrationConfigurationId: z
          .string()
          .openapi({
            param: {
              name: 'integrationConfigurationId',
              in: 'path',
              required: true,
              schema: { type: 'string' },
            },
          }),
        resourceId: z
          .string()
          .openapi({
            param: { name: 'resourceId', in: 'path', required: true, schema: { type: 'string' } },
          }),
        action: z
          .string()
          .openapi({
            param: { name: 'action', in: 'path', required: true, schema: { type: 'string' } },
          }),
      }),
      body: {
        content: {
          'application/json': {
            schema: z
              .strictObject({
                status: z.enum(['running', 'succeeded', 'failed']).exactOptional(),
                statusText: z.string().exactOptional(),
                statusUrl: z
                  .url()
                  .regex(/^https?:\/\/|^sso:/)
                  .exactOptional(),
                outcomes: z
                  .array(
                    z.xor([
                      z
                        .strictObject({
                          kind: z.string(),
                          secrets: z.array(
                            z
                              .strictObject({ name: z.string(), value: z.string() })
                              .openapi({ required: ['name', 'value'] }),
                          ),
                        })
                        .openapi({ required: ['kind', 'secrets'] }),
                      z
                        .strictObject({
                          kind: z.string(),
                          claimRules: z
                            .array(
                              z
                                .strictObject({
                                  when: z
                                    .strictObject({
                                      role: z
                                        .array(z.string().max(32))
                                        .min(1)
                                        .max(32)
                                        .exactOptional()
                                        .openapi({
                                          description:
                                            'Applies only when the token is minted for one of these roles.',
                                        }),
                                      environment: z
                                        .array(z.string())
                                        .min(1)
                                        .max(32)
                                        .exactOptional()
                                        .openapi({
                                          description:
                                            'Applies only when the token is minted for one of these environments: `production`, `preview`, `development`, or a custom environment slug. A custom environment also matches `preview`.',
                                        }),
                                    })
                                    .exactOptional()
                                    .openapi({ required: [] }),
                                  claims: z
                                    .record(
                                      z.string(),
                                      z.union([
                                        z.xor([z.string(), z.number(), z.boolean()]).nullable(),
                                        z.array(z.string()),
                                      ]),
                                    )
                                    .openapi({
                                      description:
                                        'Claims to set (string, number, boolean, or array of strings), shallow-merged over earlier rules and over the default claims. `null` removes a claim. Reserved claims cannot be set; `aud` and `sub` can be overridden with a string but not removed.',
                                    }),
                                })
                                .openapi({ required: ['claims'] }),
                            )
                            .openapi({
                              description:
                                'Ordered rules resolved at mint time. Later rules win and shallow-merge over earlier ones.',
                            }),
                        })
                        .openapi({
                          required: ['kind', 'claimRules'],
                          description:
                            'Claim rules applied after the resource’s own rules when this deployment mints a resource token. Reserved claims cannot be set.',
                        }),
                    ]),
                  )
                  .exactOptional(),
              })
              .openapi({ required: [] }),
          },
        },
      },
    },
    responses: {
      202: { description: '' },
      400: {
        description:
          'One of the provided values in the request body is invalid.\nOne of the provided values in the request query is invalid.',
      },
      401: { description: 'The request is not authorized.' },
      403: { description: 'You do not have permission to access this resource.' },
      404: { description: '' },
      410: { description: '' },
    },
    security: [{ bearerToken: [] }],
  })

