export const postV1RegistrarDomainsSearchRoute = createRoute({
  method: 'post',
  path: '/v1/registrar/domains/search',
  tags: ['domains-registrar'],
  summary: 'Get Domain Availability and Pricing',
  description:
    'Start domain research here. Get registration availability and pricing for 1–200 exact domain names. Returns results in input order, with registration and renewal prices in USD for available domains. No authentication required.',
  operationId: 'searchDomains',
  request: {
    query: z.object({
      teamId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'teamId',
            in: 'query',
            schema: { type: 'string', example: 'team_1a2b3c4d5e6f7g8h9i0j1k2l' },
            required: false,
          },
          example: 'team_1a2b3c4d5e6f7g8h9i0j1k2l',
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              domains: z
                .array(DomainNameSchema)
                .min(1)
                .max(200)
                .openapi({
                  description: 'an array of at most 200 item(s)',
                  title: 'maxItems(200)',
                }),
            })
            .openapi({ required: ['domains'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Success',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              results: z.array(
                z.union([
                  z
                    .strictObject({
                      domain: DomainNameSchema,
                      available: z
                        .literal(false)
                        .openapi({
                          description:
                            '`false` means the domain is unavailable or its availability could not be confirmed.',
                        }),
                    })
                    .openapi({ required: ['domain', 'available'] }),
                  z
                    .strictObject({
                      domain: DomainNameSchema,
                      available: z.literal(true),
                      years: z.number(),
                      price: z.number(),
                      renewalPrice: z.number(),
                      premium: z.boolean(),
                    })
                    .openapi({
                      required: [
                        'domain',
                        'available',
                        'years',
                        'price',
                        'renewalPrice',
                        'premium',
                      ],
                    }),
                ]),
              ),
            })
            .openapi({ required: ['results'] }),
        },
      },
    },
    400: {
      description: 'There was something wrong with the request',
      content: { 'application/json': { schema: HttpApiDecodeErrorSchema } },
    },
    401: {
      description: 'Unauthorized',
      content: { 'application/json': { schema: UnauthorizedSchema } },
    },
    403: {
      description: 'NotAuthorizedForScope',
      content: { 'application/json': { schema: NotAuthorizedForScopeSchema } },
    },
    429: {
      description: 'TooManyRequests',
      content: { 'application/json': { schema: TooManyRequestsSchema } },
    },
    500: {
      description: 'InternalServerError',
      content: { 'application/json': { schema: InternalServerErrorSchema } },
    },
  },
  security: [],
})

