export const postV1RegistrarDomainsDomainBuyRoute = createRoute({
  method: 'post',
  path: '/v1/registrar/domains/{domain}/buy',
  tags: ['domains-registrar'],
  summary: 'Buy a domain',
  description: 'Buy a domain',
  operationId: 'buySingleDomain',
  request: {
    params: z.object({
      domain: DomainNameSchema.openapi({
        param: {
          name: 'domain',
          in: 'path',
          schema: { $ref: '#/components/schemas/DomainName' },
          required: true,
        },
      }),
    }),
    query: z.object({
      teamId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'teamId',
            in: 'query',
            schema: { type: 'string', example: 'team_1a2b3c4d5e6f7g8h9i0j1k2l' },
            required: false,
          },
          example: 'team_1a2b3c4d5e6f7g8h9i0j1k2l',
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              autoRenew: z
                .boolean()
                .openapi({
                  description:
                    'Whether the domain should be auto-renewed before it expires. This can be configured later through the Vercel Dashboard or the [Update auto-renew for a domain](https://vercel.com/docs/rest-api/reference/endpoints/domains-registrar/update-auto-renew-for-a-domain) endpoint.',
                }),
              years: z
                .number()
                .openapi({ description: 'The number of years to purchase the domain for.' }),
              expectedPrice: z.number().min(0.01),
              contactInformation: z
                .strictObject({
                  firstName: NonEmptyTrimmedStringSchema,
                  lastName: NonEmptyTrimmedStringSchema,
                  email: EmailAddressSchema,
                  phone: E164PhoneNumberSchema,
                  address1: NonEmptyTrimmedStringSchema,
                  address2: NonEmptyTrimmedStringSchema.exactOptional(),
                  city: NonEmptyTrimmedStringSchema,
                  state: NonEmptyTrimmedStringSchema,
                  zip: NonEmptyTrimmedStringSchema,
                  country: CountryCodeSchema,
                  companyName: NonEmptyTrimmedStringSchema.exactOptional(),
                  fax: E164PhoneNumberSchema.exactOptional(),
                  additional: z.object({}).exactOptional(),
                })
                .openapi({
                  required: [
                    'firstName',
                    'lastName',
                    'email',
                    'phone',
                    'address1',
                    'city',
                    'state',
                    'zip',
                    'country',
                  ],
                  description:
                    'The contact information for the domain. Some TLDs require additional contact information. Use the [Get contact info schema](https://vercel.com/docs/rest-api/reference/endpoints/domains-registrar/get-contact-info-schema) endpoint to retrieve the required fields.',
                }),
              languageCode: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The language code for the domain. For punycode domains, this must be provided. The list of supported language codes for a TLD can be retrieved from the [Get TLD](https://vercel.com/docs/rest-api/reference/endpoints/domains-registrar/get-tld) endpoint.',
                }),
            })
            .openapi({ required: ['autoRenew', 'years', 'expectedPrice', 'contactInformation'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Success',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              orderId: OrderIdSchema,
              _links: z.record(
                z.string(),
                z
                  .strictObject({
                    href: z.string(),
                    method: z.enum(['GET', 'POST', 'PUT', 'DELETE', 'PATCH']),
                  })
                  .openapi({ required: ['href', 'method'] }),
              ),
            })
            .openapi({ required: ['orderId', '_links'] }),
        },
      },
    },
    400: {
      description: 'There was something wrong with the request',
      content: {
        'application/json': {
          schema: z.union([
            DomainTooShortSchema,
            OrderTooExpensiveSchema,
            InvalidAdditionalContactInfoSchema,
            AdditionalContactInfoRequiredSchema,
            ExpectedPriceMismatchSchema,
            DomainNotAvailableSchema,
            EmojiTldNotSupportedSchema,
            LanguageCodeRequiredSchema,
            TldNotSupportedSchema,
            HttpApiDecodeErrorSchema,
          ]),
        },
      },
    },
    401: {
      description: 'Unauthorized',
      content: { 'application/json': { schema: UnauthorizedSchema } },
    },
    403: {
      description: 'Forbidden',
      content: {
        'application/json': { schema: z.union([ForbiddenSchema, NotAuthorizedForScopeSchema]) },
      },
    },
    429: {
      description: 'TooManyRequests',
      content: { 'application/json': { schema: TooManyRequestsSchema } },
    },
    500: {
      description: 'InternalServerError',
      content: { 'application/json': { schema: InternalServerErrorSchema } },
    },
  },
  security: [{ bearerToken: [] }],
})

