export const postV1LogDrainsRoute = createRoute({
  method: 'post',
  path: '/v1/log-drains',
  tags: ['logDrains'],
  summary: 'Creates a Configurable Log Drain (deprecated)',
  description:
    'Creates a configurable log drain. This endpoint must be called with a team AccessToken (integration OAuth2 clients are not allowed)',
  operationId: 'createConfigurableLogDrain',
  request: {
    query: z.object({
      teamId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The Team identifier to perform the request on behalf of.',
            in: 'query',
            name: 'teamId',
            schema: { type: 'string', example: 'team_1a2b3c4d5e6f7g8h9i0j1k2l' },
            required: false,
          },
          example: 'team_1a2b3c4d5e6f7g8h9i0j1k2l',
        }),
      slug: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The Team slug to perform the request on behalf of.',
            in: 'query',
            name: 'slug',
            schema: { type: 'string', example: 'my-team-url-slug' },
            required: false,
          },
          example: 'my-team-url-slug',
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              deliveryFormat: z
                .enum(['json', 'ndjson'])
                .openapi({ description: 'The delivery log format', example: 'json' }),
              url: z
                .url()
                .regex(/^(http|https)?:\/\//)
                .openapi({ description: 'The log drain url' }),
              headers: z
                .record(z.string(), z.string())
                .exactOptional()
                .openapi({ description: 'Headers to be sent together with the request' }),
              projectIds: z
                .array(z.string().regex(/^[a-zA-z0-9_]+$/))
                .min(1)
                .max(50)
                .exactOptional(),
              sources: z
                .array(z.enum(['static', 'lambda', 'build', 'edge', 'external', 'firewall']))
                .min(1)
                .superRefine((items, ctx) => {
                  const seen = new Map()
                  for (const [i, val] of items.entries()) {
                    const key = JSON.stringify(val)
                    if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                    else seen.set(key, i)
                  }
                }),
              environments: z
                .array(z.enum(['preview', 'production']))
                .min(1)
                .superRefine((items, ctx) => {
                  const seen = new Map()
                  for (const [i, val] of items.entries()) {
                    const key = JSON.stringify(val)
                    if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                    else seen.set(key, i)
                  }
                })
                .exactOptional(),
              secret: z
                .string()
                .exactOptional()
                .openapi({ description: 'Custom secret of log drain' }),
              samplingRate: z
                .number()
                .min(0.01)
                .max(1)
                .multipleOf(0.01)
                .exactOptional()
                .openapi({
                  description:
                    'The sampling rate for this log drain. It should be a percentage rate between 0 and 100. With max 2 decimal points',
                }),
              name: z
                .string()
                .exactOptional()
                .openapi({ description: 'The custom name of this log drain.' }),
            })
            .openapi({ required: ['deliveryFormat', 'url', 'sources'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: { description: '', content: { 'application/json': { schema: z.object({}) } } },
    400: { description: 'One of the provided values in the request body is invalid.' },
    401: { description: 'The request is not authorized.' },
    403: { description: 'You do not have permission to access this resource.' },
    404: { description: '' },
    410: { description: '' },
  },
  security: [{ bearerToken: [] }],
})

