export const postV1KmsIssuersIssuerIdSignMessageRoute = createRoute({
  method: 'post',
  path: '/v1/kms/issuers/{issuerId}/sign/message',
  tags: ['kms'],
  summary: 'Sign a message',
  description:
    "Sign a raw message with a KMS issuer's active signing key. Authenticate the request with a Vercel OIDC token in the `Authorization: Bearer` header; the issuer's policies decide which workloads are allowed to sign. The response `signature` is standard-base64 of the raw signature over the decoded message bytes. `keyId`, `algorithm`, and `fingerprint` identify the signing key in the issuer's JWKS.",
  operationId: 'signKmsMessage',
  request: {
    params: z.object({
      issuerId: z
        .string()
        .openapi({
          param: {
            name: 'issuerId',
            description: 'The ID of the issuer.',
            in: 'path',
            required: true,
            schema: { type: 'string', description: 'The ID of the issuer.' },
          },
          description: 'The ID of the issuer.',
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              message: z
                .string()
                .regex(/^[A-Za-z0-9+\/]*={0,2}$/)
                .max(44000)
                .openapi({ description: 'Base64-encoded message to be signed.' }),
            })
            .openapi({ required: ['message'] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              algorithm: z.string().openapi({ description: 'Algorithm of the signing key.' }),
              fingerprint: z
                .string()
                .openapi({
                  description:
                    "SHA-256 fingerprint of the signing key's public key (`SHA256:<base64>`).",
                }),
              keyId: z
                .string()
                .openapi({
                  description:
                    'Key id of the signing key. Matches the JWKS `kid` so verifiers can select the key after rotation without trial-verifying every published key.',
                }),
              signature: z
                .string()
                .openapi({
                  description:
                    'Standard-base64 encoding of the raw signature over the decoded message bytes.',
                }),
            })
            .openapi({ required: ['algorithm', 'fingerprint', 'keyId', 'signature'] }),
        },
      },
    },
    400: {
      description:
        'One of the provided values in the request body is invalid.\nOne of the provided values in the request query is invalid.',
    },
    401: { description: '' },
    403: { description: '' },
    404: { description: '' },
    429: { description: '' },
  },
  security: [{ bearerToken: [] }],
})

