export const patchV1ProjectsIdOrNameSharedConnectLinksRoute = createRoute({
  method: 'patch',
  path: '/v1/projects/{idOrName}/shared-connect-links',
  tags: ['networking', 'static-ips'],
  summary: 'Configures Static IPs for a project',
  description: 'Allows configuring Static IPs for a project',
  operationId: 'updateStaticIps',
  request: {
    params: z.object({
      idOrName: z
        .string()
        .openapi({
          param: {
            name: 'idOrName',
            description: 'The unique project identifier or the project name',
            in: 'path',
            required: true,
            schema: {
              description: 'The unique project identifier or the project name',
              type: 'string',
            },
          },
          description: 'The unique project identifier or the project name',
        }),
    }),
    query: z.object({
      teamId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The Team identifier to perform the request on behalf of.',
            in: 'query',
            name: 'teamId',
            schema: { type: 'string', example: 'team_1a2b3c4d5e6f7g8h9i0j1k2l' },
            required: false,
          },
          example: 'team_1a2b3c4d5e6f7g8h9i0j1k2l',
        }),
      slug: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The Team slug to perform the request on behalf of.',
            in: 'query',
            name: 'slug',
            schema: { type: 'string', example: 'my-team-url-slug' },
            required: false,
          },
          example: 'my-team-url-slug',
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .union([
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'builds')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ required: ['builds'] }),
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'regions')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ required: ['regions'] }),
            ])
            .and(
              z
                .object({
                  builds: z
                    .boolean()
                    .exactOptional()
                    .openapi({ description: 'Whether to use Static IPs for builds.' }),
                  regions: z
                    .array(
                      z
                        .string()
                        .max(4)
                        .openapi({
                          description: 'The region in which to enable Static IPs.',
                          example: 'iad1',
                        }),
                    )
                    .min(0)
                    .max(3)
                    .superRefine((items, ctx) => {
                      const seen = new Map()
                      for (const [i, val] of items.entries()) {
                        const key = JSON.stringify(val)
                        if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                        else seen.set(key, i)
                      }
                    })
                    .exactOptional(),
                })
                .openapi({ required: [] }),
            ),
        },
      },
    },
  },
  responses: {
    200: {
      description: '',
      content: {
        'application/json': {
          schema: z.array(
            z
              .object({
                aws: z
                  .object({
                    securityGroupId: z.string().exactOptional(),
                    subnetIds: z.array(z.string()),
                  })
                  .exactOptional()
                  .openapi({ required: ['subnetIds'] }),
                buildsEnabled: z.union([z.literal(false), z.literal(true)]),
                connectConfigurationId: z.string(),
                createdAt: z.number(),
                dc: z.string().exactOptional(),
                envId: z.xor([z.string(), z.enum(['preview', 'production'])]),
                passive: z.union([z.literal(false), z.literal(true)]),
                updatedAt: z.number(),
              })
              .openapi({
                required: [
                  'buildsEnabled',
                  'connectConfigurationId',
                  'createdAt',
                  'envId',
                  'passive',
                  'updatedAt',
                ],
              }),
          ),
        },
      },
    },
    400: {
      description:
        'One of the provided values in the request body is invalid.\nOne of the provided values in the request query is invalid.',
    },
    401: { description: 'The request is not authorized.' },
    402: { description: '' },
    403: { description: 'You do not have permission to access this resource.' },
    404: { description: '' },
    409: { description: '' },
    410: { description: '' },
    500: { description: '' },
  },
  security: [{ bearerToken: [] }],
})

