export const postV2FilesRoute = createRoute({
  method: 'post',
  path: '/v2/files',
  tags: ['deployments'],
  summary: 'Upload Deployment Files',
  description:
    "Before you create a deployment you need to upload the required files for that deployment. To do it, you need to first upload each file to this endpoint. Once that's completed, you can create a new deployment with the uploaded files. The file content must be placed inside the body of the request. In the case of a successful response you'll receive a status code 200 with an empty body.",
  operationId: 'uploadFile',
  request: {
    headers: z.object({
      'Content-Length': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'header',
            description: 'The file size in bytes',
            schema: { description: 'The file size in bytes', type: 'number' },
            name: 'Content-Length',
            required: false,
          },
          description: 'The file size in bytes',
        }),
      'x-vercel-digest': z
        .string()
        .max(40)
        .exactOptional()
        .openapi({
          param: {
            in: 'header',
            description: 'The file SHA1 used to check the integrity',
            schema: {
              type: 'string',
              description: 'The file SHA1 used to check the integrity',
              maxLength: 40,
            },
            name: 'x-vercel-digest',
            required: false,
          },
          description: 'The file SHA1 used to check the integrity',
        }),
      'x-now-digest': z
        .string()
        .max(40)
        .exactOptional()
        .openapi({
          param: {
            in: 'header',
            description: 'The file SHA1 used to check the integrity',
            schema: {
              type: 'string',
              description: 'The file SHA1 used to check the integrity',
              maxLength: 40,
              deprecated: true,
            },
            name: 'x-now-digest',
            required: false,
          },
          description: 'The file SHA1 used to check the integrity',
          deprecated: true,
        }),
      'x-now-size': z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .exactOptional()
        .openapi({
          param: {
            in: 'header',
            description: 'The file size as an alternative to `Content-Length`',
            schema: {
              type: 'number',
              deprecated: true,
              description: 'The file size as an alternative to `Content-Length`',
            },
            name: 'x-now-size',
            required: false,
          },
          deprecated: true,
          description: 'The file size as an alternative to `Content-Length`',
        }),
    }),
    query: z.object({
      teamId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The Team identifier to perform the request on behalf of.',
            in: 'query',
            name: 'teamId',
            schema: { type: 'string', example: 'team_1a2b3c4d5e6f7g8h9i0j1k2l' },
            required: false,
          },
          example: 'team_1a2b3c4d5e6f7g8h9i0j1k2l',
        }),
      slug: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The Team slug to perform the request on behalf of.',
            in: 'query',
            name: 'slug',
            schema: { type: 'string', example: 'my-team-url-slug' },
            required: false,
          },
          example: 'my-team-url-slug',
        }),
    }),
    body: {
      content: {
        'application/octet-stream': {
          schema: z.file().openapi({ type: 'string', format: 'binary' }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'File already uploaded\nFile successfully uploaded',
      content: {
        'application/json': {
          schema: z.xor([
            z
              .object({
                urls: z
                  .array(z.string())
                  .openapi({
                    description: 'Array of URLs where the file was updated',
                    example: ['example-upload.aws.com'],
                  }),
              })
              .openapi({ required: ['urls'] }),
            z.object({}),
          ]),
        },
      },
    },
    400: {
      description:
        'One of the provided values in the headers is invalid\nDigest is not valid\nFile size is not valid',
    },
    401: { description: 'The request is not authorized.' },
    403: { description: 'You do not have permission to access this resource.' },
    404: { description: '' },
    410: { description: '' },
    426: { description: '' },
  },
  security: [{ bearerToken: [] }],
})

