export const postV2DeploymentsIdAliasesRoute = createRoute({
  method: 'post',
  path: '/v2/deployments/{id}/aliases',
  tags: ['aliases'],
  summary: 'Assign an Alias',
  description:
    'Creates a new alias for the deployment resolved from the given deployment or alias ID or URL. The authenticated user or team must own this deployment. If the desired alias is already assigned to another deployment, then it will be removed from the old deployment and assigned to the new one.',
  operationId: 'assignAlias',
  request: {
    params: z.object({
      id: z
        .xor([z.string()])
        .openapi({
          param: {
            name: 'id',
            description: 'The deployment or alias ID or URL to assign from',
            in: 'path',
            required: true,
            schema: {
              description: 'The deployment or alias ID or URL to assign from',
              example: 'dpl_FjvFJncQHQcZMznrUm9EoB8sFuPa',
              oneOf: [{ type: 'string' }],
            },
          },
          description: 'The deployment or alias ID or URL to assign from',
          example: 'dpl_FjvFJncQHQcZMznrUm9EoB8sFuPa',
        }),
    }),
    query: z.object({
      teamId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The Team identifier to perform the request on behalf of.',
            in: 'query',
            name: 'teamId',
            schema: { type: 'string', example: 'team_1a2b3c4d5e6f7g8h9i0j1k2l' },
            required: false,
          },
          example: 'team_1a2b3c4d5e6f7g8h9i0j1k2l',
        }),
      slug: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The Team slug to perform the request on behalf of.',
            in: 'query',
            name: 'slug',
            schema: { type: 'string', example: 'my-team-url-slug' },
            required: false,
          },
          example: 'my-team-url-slug',
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              alias: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'The alias we want to assign to the deployment defined in the URL',
                  example: 'my-alias.vercel.app',
                }),
              redirect: z
                .string()
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'The redirect property will take precedence over the deployment id from the URL and consists of a hostname (like test.com) to which the alias should redirect using status code 307',
                  example: null,
                }),
            })
            .openapi({ required: [] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'The alias was successfully assigned to the deployment',
      content: {
        'application/json': {
          schema: z
            .object({
              alias: z
                .string()
                .openapi({
                  description: 'The assigned alias name',
                  example: 'my-alias.vercel.app',
                }),
              created: z.iso
                .datetime({ offset: true })
                .openapi({
                  description: 'The date when the alias was created',
                  example: '2017-04-26T23:00:34.232Z',
                }),
              oldDeploymentId: z
                .string()
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'The unique identifier of the previously aliased deployment, only received when the alias was used before',
                  example: 'dpl_FjvFJncQHQcZMznrUm9EoB8sFuPa',
                }),
              uid: z
                .string()
                .openapi({
                  description: 'The unique identifier of the alias',
                  example: '2WjyKQmM8ZnGcJsPWMrHRHrE',
                }),
            })
            .openapi({ required: ['alias', 'created', 'uid'] }),
        },
      },
    },
    400: {
      description:
        'One of the provided values in the request body is invalid.\nOne of the provided values in the request query is invalid.\nThe cert for the provided alias is not ready\nThe deployment is not READY and can not be aliased\nThe supplied alias is invalid',
    },
    401: { description: 'The request is not authorized.' },
    402: { description: 'The account is missing a payment so payment method must be updated' },
    403: {
      description:
        'You do not have permission to access this resource.\nIf no .vercel.app alias exists then we fail (nothing to mirror)',
    },
    404: {
      description: 'The domain used for the alias was not found\nThe deployment was not found',
    },
    409: {
      description:
        'The provided alias is already assigned to the given deployment\nThe domain is not allowed to be used',
    },
    410: { description: '' },
  },
  security: [{ bearerToken: [] }],
})

